// External black-box probe for the runtime wire contract.
//
// The allowlist table, the fuzzers and the reflective surface test live beside
// the package and prove the RoundTripper in isolation. This file proves the
// other half: that the client the loader actually builds — through New and
// Observe, with no access to package internals — puts only allowlisted
// requests on the wire, retries a silent peer exactly once, and never leaks a
// credential, path or server URL in a failure message.
//
// Hermetic: loopback TLS fixtures, certificates generated by the fixture,
// kubeconfigs in t.TempDir, no cluster and no external network.
package kube_test

import (
	"context"
	"crypto/ecdsa"
	"crypto/elliptic"
	"crypto/rand"
	"crypto/x509"
	"crypto/x509/pkix"
	"encoding/base64"
	"encoding/pem"
	"fmt"
	"io"
	"math/big"
	"net"
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"sync/atomic"
	"testing"
	"time"

	"github.com/Hedronite/scry/internal/exitcode"
	"github.com/Hedronite/scry/internal/kube"
	"github.com/Hedronite/scry/internal/report"
)

type probeRequest struct {
	method   string
	path     string
	rawQuery string
}

// probeFixture is a loopback TLS apiserver that records every request and every
// accepted connection.
type probeFixture struct {
	srv   *httptest.Server
	ca    string
	mu    sync.Mutex
	reqs  []probeRequest
	conns atomic.Int64
}

func newProbeFixture(t *testing.T, h http.HandlerFunc) *probeFixture {
	t.Helper()
	f := &probeFixture{}
	srv := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		f.mu.Lock()
		f.reqs = append(f.reqs, probeRequest{method: r.Method, path: r.URL.Path, rawQuery: r.URL.RawQuery})
		f.mu.Unlock()
		h(w, r)
	}))
	srv.Config.ConnState = func(_ net.Conn, state http.ConnState) {
		if state == http.StateNew {
			f.conns.Add(1)
		}
	}
	srv.StartTLS()
	t.Cleanup(srv.Close)
	f.srv = srv
	f.ca = base64.StdEncoding.EncodeToString(pem.EncodeToMemory(&pem.Block{
		Type:  "CERTIFICATE",
		Bytes: srv.Certificate().Raw,
	}))
	return f
}

func (f *probeFixture) requests() []probeRequest {
	f.mu.Lock()
	defer f.mu.Unlock()
	return append([]probeRequest(nil), f.reqs...)
}

func (f *probeFixture) paths() []string {
	out := make([]string, 0, len(f.requests()))
	for _, r := range f.requests() {
		out = append(out, r.path)
	}
	return out
}

// probeSignals answers the three readiness signals the way a stock apiserver
// would.
func probeSignals() http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/readyz", "/livez":
			_, _ = io.WriteString(w, "ok\n")
		case "/version":
			_, _ = io.WriteString(w, `{"major":"1","minor":"34","gitVersion":"v1.34.0+h3s"}`)
		case "/api/v1/nodes":
			w.Header().Set("Content-Type", "application/json")
			_, _ = io.WriteString(w, `{"apiVersion":"v1","kind":"NodeList","items":[`+
				`{"metadata":{"name":"node-a"},"status":{"conditions":[`+
				`{"type":"Ready","status":"True","reason":"KubeletReady"}]}}]}`)
		default:
			http.NotFound(w, r)
		}
	}
}

// probeKubeconfig writes a synthetic kubeconfig pointing at the fixture. It is
// plain YAML on purpose: it must not depend on the helpers the package's own
// tests use, or a change there could hide a regression here.
func (f *probeFixture) probeKubeconfig(t *testing.T, userBlock string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "kubeconfig")
	body := fmt.Sprintf(`apiVersion: v1
kind: Config
clusters:
- name: c
  cluster:
    server: %s
    certificate-authority-data: %s
contexts:
- name: ctx
  context:
    cluster: c
    user: u
current-context: ctx
users:
- name: u
  user:
%s
`, f.srv.URL, f.ca, userBlock)
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatalf("write kubeconfig: %v", err)
	}
	return path
}

// probeStrangerCA returns a self-signed CA unrelated to any fixture. httptest
// serves one baked-in certificate to every TLS server, so a second fixture is
// not a stranger.
func probeStrangerCA(t *testing.T) string {
	t.Helper()
	key, err := ecdsa.GenerateKey(elliptic.P256(), rand.Reader)
	if err != nil {
		t.Fatalf("generate key: %v", err)
	}
	template := &x509.Certificate{
		SerialNumber:          big.NewInt(2),
		Subject:               pkix.Name{CommonName: "stranger"},
		NotBefore:             time.Now().Add(-time.Hour),
		NotAfter:              time.Now().Add(time.Hour),
		KeyUsage:              x509.KeyUsageCertSign,
		BasicConstraintsValid: true,
		IsCA:                  true,
	}
	der, err := x509.CreateCertificate(rand.Reader, template, template, &key.PublicKey, key)
	if err != nil {
		t.Fatalf("create certificate: %v", err)
	}
	return base64.StdEncoding.EncodeToString(pem.EncodeToMemory(&pem.Block{Type: "CERTIFICATE", Bytes: der}))
}

func probeWantError(t *testing.T, err error, reason exitcode.Reason, code exitcode.Code) {
	t.Helper()
	if err == nil {
		t.Fatalf("want a %s error, got nil", reason)
	}
	e, ok := exitcode.Of(err)
	if !ok || e == nil {
		t.Fatalf("want a typed error, got %T: %v", err, err)
	}
	if e.Reason != reason || e.Code != code {
		t.Fatalf("want %s (exit %d), got %s (exit %d): %v", reason, code, e.Reason, e.Code, err)
	}
}

func probeWantRedacted(t *testing.T, err error, secrets ...string) {
	t.Helper()
	if err == nil {
		return
	}
	for _, secret := range secrets {
		if secret != "" && strings.Contains(err.Error(), secret) {
			t.Fatalf("failure message leaks %q: %q", secret, err.Error())
		}
	}
}

// TestProbeObserveIssuesOnlyAllowlistedRequests is the wire contract: a healthy
// observation is exactly three GETs of the allowlisted shapes, in order, with
// no watch parameter anywhere.
func TestProbeObserveIssuesOnlyAllowlistedRequests(t *testing.T) {
	f := newProbeFixture(t, probeSignals())
	client, err := kube.New(kube.Options{Kubeconfig: f.probeKubeconfig(t, "    token: test-token")})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	obs := client.Observe(context.Background())
	if obs.Failure != nil {
		t.Fatalf("Observe: %v", obs.Failure)
	}

	got := f.requests()
	want := []string{"/readyz", "/version", "/api/v1/nodes"}
	if len(got) != len(want) {
		t.Fatalf("requests = %+v, want %d", got, len(want))
	}
	for i, path := range want {
		if got[i].method != http.MethodGet || got[i].path != path {
			t.Fatalf("request %d = %s %s, want GET %s", i, got[i].method, got[i].path, path)
		}
		if strings.Contains(got[i].rawQuery, "watch") {
			t.Fatalf("request %d carried a watch parameter: %q", i, got[i].rawQuery)
		}
	}
	if got[0].rawQuery != "verbose=true" {
		t.Fatalf("/readyz query = %q, want verbose=true", got[0].rawQuery)
	}
	if got[1].rawQuery != "" {
		t.Fatalf("/version query = %q, want none", got[1].rawQuery)
	}

	if obs.Apiserver.Result != report.Up {
		t.Fatalf("apiserver result = %q, want up", obs.Apiserver.Result)
	}
	if obs.Readyz == nil || !obs.Readyz.OK {
		t.Fatalf("readyz = %+v, want ok", obs.Readyz)
	}
	if obs.Server == nil || obs.Server.Flavor != "h3s" {
		t.Fatalf("server = %+v, want flavor h3s", obs.Server)
	}
	if obs.Nodes == nil || obs.Nodes.Total != 1 || obs.Nodes.Ready != 1 {
		t.Fatalf("nodes = %+v, want 1 total and 1 ready", obs.Nodes)
	}
}

// TestProbeFailedReadyzAddsTheLivezDiagnostic proves the conditional fourth
// request is the allowlisted diagnostic and nothing else.
func TestProbeFailedReadyzAddsTheLivezDiagnostic(t *testing.T) {
	f := newProbeFixture(t, func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/readyz" {
			w.WriteHeader(http.StatusInternalServerError)
			_, _ = io.WriteString(w, "[-]etcd failed: unreachable\nreadyz check failed\n")
			return
		}
		probeSignals()(w, r)
	})
	client, err := kube.New(kube.Options{Kubeconfig: f.probeKubeconfig(t, "    token: test-token")})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	obs := client.Observe(context.Background())

	want := []string{"/readyz", "/livez", "/version", "/api/v1/nodes"}
	if got := f.paths(); strings.Join(got, ",") != strings.Join(want, ",") {
		t.Fatalf("paths = %v, want %v", got, want)
	}
	if obs.Readyz == nil || obs.Readyz.OK {
		t.Fatalf("readyz = %+v, want failed", obs.Readyz)
	}
	if obs.Apiserver.Livez != "ok" {
		t.Fatalf("livez = %q, want ok", obs.Apiserver.Livez)
	}
}

// TestProbeRedirectIsRefusedAtTheFirstHop proves a redirect never reaches the
// host it points at, even when the target path would be allowlisted.
func TestProbeRedirectIsRefusedAtTheFirstHop(t *testing.T) {
	elsewhere := newProbeFixture(t, probeSignals())
	origin := newProbeFixture(t, func(w http.ResponseWriter, r *http.Request) {
		http.Redirect(w, r, elsewhere.srv.URL+"/readyz", http.StatusFound)
	})
	client, err := kube.New(kube.Options{Kubeconfig: origin.probeKubeconfig(t, "    token: test-token")})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	obs := client.Observe(context.Background())
	probeWantError(t, obs.Failure, exitcode.AllowlistDenied, exitcode.Internal)
	if got := len(elsewhere.requests()); got != 0 {
		t.Fatalf("the redirect reached the second server %d time(s)", got)
	}
	if got := elsewhere.conns.Load(); got != 0 {
		t.Fatalf("the redirect opened %d connection(s) to the second server", got)
	}
}

// TestProbeSilentPeerIsUnknownAndRetriedOnce pins the transport verdict and the
// single retry: a peer that completes TCP and then says nothing is unobserved,
// never down.
func TestProbeSilentPeerIsUnknownAndRetriedOnce(t *testing.T) {
	f := newProbeFixture(t, func(w http.ResponseWriter, r *http.Request) {
		<-r.Context().Done()
	})
	client, err := kube.New(kube.Options{
		Kubeconfig: f.probeKubeconfig(t, "    token: test-token"),
		Timeout:    100 * time.Millisecond,
	})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	obs := client.Observe(context.Background())
	if obs.Apiserver.Result != report.Unknown {
		t.Fatalf("apiserver result = %q, want unknown", obs.Apiserver.Result)
	}
	probeWantError(t, obs.Failure, exitcode.HTTPUnresponsive, exitcode.Transport)
	if got := len(f.requests()); got != 2 {
		t.Fatalf("silent peer saw %d request(s), want 2 (one retry)", got)
	}
}

// TestProbeExecutorIsRefusedBeforeAnyConnection is the end-to-end half of the
// exec canary: no marker file, and no TCP connection to the server named in the
// kubeconfig.
func TestProbeExecutorIsRefusedBeforeAnyConnection(t *testing.T) {
	f := newProbeFixture(t, probeSignals())
	marker := filepath.Join(t.TempDir(), "exec-ran")
	path := f.probeKubeconfig(t, fmt.Sprintf(
		"    exec:\n      command: /bin/sh\n      args: [\"-c\", \"touch %s\"]\n", marker))
	_, err := kube.New(kube.Options{Kubeconfig: path})
	probeWantError(t, err, exitcode.ExecAuthRefused, exitcode.Config)
	if _, statErr := os.Stat(marker); !os.IsNotExist(statErr) {
		t.Fatalf("the exec plugin ran: marker exists")
	}
	if got := f.conns.Load(); got != 0 {
		t.Fatalf("a refused kubeconfig opened %d connection(s)", got)
	}
	probeWantRedacted(t, err, path, f.srv.URL, "test-token")
}

// TestProbeExecInSecondKubeconfigFileIsRefused proves the refusal scans the
// merged config, not just the first file in KUBECONFIG precedence.
func TestProbeExecInSecondKubeconfigFileIsRefused(t *testing.T) {
	f := newProbeFixture(t, probeSignals())
	first := f.probeKubeconfig(t, "    token: test-token")
	second := filepath.Join(t.TempDir(), "second")
	body := fmt.Sprintf(`apiVersion: v1
kind: Config
clusters:
- name: c2
  cluster:
    server: %s
    certificate-authority-data: %s
contexts:
- name: ctx2
  context: {cluster: c2, user: u2}
users:
- name: u2
  user:
    exec:
      command: /bin/sh
`, f.srv.URL, f.ca)
	if err := os.WriteFile(second, []byte(body), 0o600); err != nil {
		t.Fatalf("write second kubeconfig: %v", err)
	}
	t.Setenv("KUBECONFIG", first+string(os.PathListSeparator)+second)
	_, err := kube.New(kube.Options{AllowEnv: true})
	probeWantError(t, err, exitcode.ExecAuthRefused, exitcode.Config)
	if got := f.conns.Load(); got != 0 {
		t.Fatalf("a refused kubeconfig opened %d connection(s)", got)
	}
	probeWantRedacted(t, err, first, second, f.srv.URL)
}

// TestProbeAuthFailureClassifiesAndRedacts pins exit 4 and the absence of the
// credential, kubeconfig path and server URL in the message.
func TestProbeAuthFailureClassifiesAndRedacts(t *testing.T) {
	const token = "probe-token-do-not-print"
	f := newProbeFixture(t, func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusUnauthorized)
	})
	path := f.probeKubeconfig(t, "    token: "+token)
	client, err := kube.New(kube.Options{Kubeconfig: path})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	obs := client.Observe(context.Background())
	probeWantError(t, obs.Failure, exitcode.AuthRejected, exitcode.Auth)
	probeWantRedacted(t, obs.Failure, token, path, f.srv.URL)
}

// TestProbeTLSVerifyFailureIsUpAndExitFive pins the D1 rule end to end: a
// certificate failure means the peer answered, so the result is up, the exit is
// 5, and the message names no location.
func TestProbeTLSVerifyFailureIsUpAndExitFive(t *testing.T) {
	f := newProbeFixture(t, probeSignals())
	path := filepath.Join(t.TempDir(), "kubeconfig")
	body := fmt.Sprintf(`apiVersion: v1
kind: Config
clusters:
- name: c
  cluster:
    server: %s
    certificate-authority-data: %s
contexts:
- name: ctx
  context: {cluster: c, user: u}
current-context: ctx
users:
- name: u
  user:
    token: test-token
`, f.srv.URL, probeStrangerCA(t))
	if err := os.WriteFile(path, []byte(body), 0o600); err != nil {
		t.Fatalf("write kubeconfig: %v", err)
	}
	client, err := kube.New(kube.Options{Kubeconfig: path})
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	obs := client.Observe(context.Background())
	if obs.Apiserver.Result != report.Up {
		t.Fatalf("result = %q, want up: a certificate failure is still an answer", obs.Apiserver.Result)
	}
	probeWantError(t, obs.Failure, exitcode.TLSVerifyFailed, exitcode.TLS)
	probeWantRedacted(t, obs.Failure, path, f.srv.URL, "127.0.0.1")
}
